from pathlib import Path
import re,shutil,json,hashlib
C=Path('/workspace/work/deliverables/confluence/collection/confluence');R=C.parent.parent/'review'
def add(folder,s):
 p=C/'elements'/folder/'element.css';p.write_text(p.read_text()+s+'\n')
q='.cycle[data-el="confluence-cycle"]'
add('cycle',f'''{q} .core{{grid-row:1 / span 3;aspect-ratio:1;height:auto;align-self:center}}{q}::before{{left:20%;right:20%;top:15%;bottom:15%;width:auto;height:auto;border:var(--stroke) solid var(--n-3);background:none;border-radius:50%}}{q}::after{{left:auto;right:calc(20% - 5px);top:50%;bottom:auto;width:10px;height:10px;border-top:2px solid var(--a1);border-right:2px solid var(--a1);background:none;transform:rotate(135deg)}}@container (max-width:650px){{{q} .core .name{{font-size:var(--type-20)}}}}''')
q='.sankey[data-el="confluence-sankey"]'
add('sankey',f'''{q}{{grid-template-columns:1fr 2fr}}{q}:has(>.branch:nth-child(4):last-child)>.branch{{grid-row:span 2}}{q}:has(>.branch:nth-child(3):last-child)>.branch{{grid-row:span 3}}{q}>.branch{{display:grid;grid-template-columns:1fr 1fr;gap:calc(var(--gap-sm)/2);padding:var(--gap-sm);align-content:center}}{q}>.branch>.fig{{text-align:right;font-size:var(--type-24)}}{q} .source .fig{{font-size:var(--type-32)}}{q} .branch .name{{font-size:var(--type-18)}}{q} .branch .branch{{grid-column:1 / -1;display:flex;justify-content:space-between;align-items:center;gap:var(--gap-sm);padding:calc(var(--gap-sm)/2);background:var(--a1-1-soft);border-left:calc(2px + var(--v)*.1px) solid var(--a1-3-soft)}}{q} .branch .branch .fig{{font-size:var(--type-20)}}{q} .branch .branch.out{{border-color:var(--n-3)}}''')
q='.slope[data-el="confluence-slope"]'
add('slope',f'''{q}:not(.dumbbell){{display:block;container-type:size;anchor-scope:all;padding:0;isolation:isolate}}{q}:not(.dumbbell) .heads{{position:absolute;top:var(--gap-lg);left:20%;right:20%;padding:0;border:0;font-size:var(--type-14)}}{q}:not(.dumbbell) .pair{{display:contents}}{q}:not(.dumbbell) .pair>.name{{position:absolute;top:0;max-width:20%;font-size:var(--type-14);color:var(--n-7)}}{q}:not(.dumbbell) .pair.on>.name{{color:var(--a1-8)}}{q}:not(.dumbbell) .pair>.a,{q}:not(.dumbbell) .pair>.b{{position:absolute;left:20%;top:calc(72px + (100cqh - 108px)*(1 - var(--a)/var(--max)));bottom:auto;width:8px;height:8px;display:block;padding:0;border:0;border-radius:50%;background:var(--n-5);transform:translate(-50%,-50%);z-index:2;anchor-name:var(--confluence-slope-a)}}{q}:not(.dumbbell) .pair>.b{{left:80%;top:calc(72px + (100cqh - 108px)*(1 - var(--b)/var(--max)));anchor-name:var(--confluence-slope-b)}}{q}:not(.dumbbell) .pair.on>.a,{q}:not(.dumbbell) .pair.on>.b{{background:var(--a1)}}{q}:not(.dumbbell) .pair>.a span,{q}:not(.dumbbell) .pair>.b span{{position:absolute;right:calc(100% + 8px);top:-5px;width:52px;text-align:right;color:var(--ink);font-size:var(--type-14);line-height:var(--label-line);white-space:nowrap}}{q}:not(.dumbbell) .pair>.b span{{left:calc(100% + 8px);right:auto;text-align:left}}{q}:not(.dumbbell) .pair::before,{q}:not(.dumbbell) .pair::after{{content:"";position:absolute;left:anchor(var(--confluence-slope-a) center);right:anchor(var(--confluence-slope-b) center);width:auto;height:auto;background:var(--n-4);z-index:1}}{q}:not(.dumbbell) .pair.on::before,{q}:not(.dumbbell) .pair.on::after{{background:var(--a1)}}{q}:not(.dumbbell) .pair::before{{top:anchor(var(--confluence-slope-b) center);bottom:anchor(var(--confluence-slope-a) center);clip-path:polygon(0 calc(100% - 1px),100% 0,100% 1px,0 100%)}}{q}:not(.dumbbell) .pair::after{{top:anchor(var(--confluence-slope-a) center);bottom:anchor(var(--confluence-slope-b) center);clip-path:polygon(0 0,100% calc(100% - 1px),100% 100%,0 1px)}}{q}:has(>.pair:nth-child(3):last-child):not(.dumbbell) .pair>.name{{max-width:50%}}{q}:has(>.pair:nth-child(3):last-child):not(.dumbbell) .pair:nth-child(2 of .pair)>.name{{left:50%}}{q}:not(.dumbbell) .pair:nth-child(4 of .pair)>.a span{{top:8px}}{q}:not(.dumbbell) .pair:nth-child(5 of .pair)>.a span{{top:-22px}}{q}:not(.dumbbell) .pair:nth-child(4 of .pair)>.b span{{top:-22px}}{q}:not(.dumbbell) .pair:nth-child(5 of .pair)>.b span{{top:8px}}{q}.dumbbell .pair>.a,{q}.dumbbell .pair>.b{{width:8px;height:8px;border:0}}{q}.dumbbell .pair>.a span,{q}.dumbbell .pair>.b span{{position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);font-size:var(--type-14);color:var(--ink);white-space:nowrap}}{q}.dumbbell .pair>.b span{{top:calc(100% + 8px);bottom:auto}}''')
for i in range(1,9):
 add('slope',f'''{q}:not(.dumbbell) .pair:nth-child({i} of .pair){{--confluence-slope-a:--confluence-slope-a{i};--confluence-slope-b:--confluence-slope-b{i}}}{q}:not(.dumbbell) .pair:nth-child({i} of .pair)>.name{{left:{(i-1)*20}%}}''')
# Keep the two-member legend balanced after the general index rules.
add('slope',f'{q}:has(>.pair:nth-child(3):last-child):not(.dumbbell) .pair:nth-child(2 of .pair)>.name'+'{left:50%}')
for f in (C/'elements/slope/fixtures').glob('*.html'):
 s=f.read_text();s=re.sub(r'(<b class="[ab]">)([^<]+)(</b>)',r'\1<span>\2</span>\3',s)
 if f.stem=='dumbbell-6':s=s.replace('<!-- min: 6x3 -->','<!-- min: 6x4 -->')
 f.write_text(s)
for f in C.rglob('*.css'):shutil.copy(f,R/'assets/collection'/f.relative_to(C))
(R/'source-manifest.json').write_text(json.dumps({str(p.relative_to(C)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(C.rglob('*')) if p.is_file()},indent=2))

p=C/'elements/slope/element.css';p.write_text(p.read_text()+Path(__file__).with_name('slope_geometry.css').read_text())
for f in C.rglob('*.css'):shutil.copy(f,R/'assets/collection'/f.relative_to(C))
(R/'source-manifest.json').write_text(json.dumps({str(p.relative_to(C)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(C.rglob('*')) if p.is_file()},indent=2))
